package dev.isylxnt.duskcontracts.api.event;
import dev.isylxnt.duskcontracts.api.ContractView; import org.bukkit.event.Event; import org.bukkit.event.HandlerList;
public final class ContractCancelledEvent extends Event { private static final HandlerList HANDLERS=new HandlerList(); private final ContractView contract; private final String reason; public ContractCancelledEvent(ContractView contract,String reason,boolean async){super(async);this.contract=contract;this.reason=reason;} public ContractView contract(){return contract;} public String reason(){return reason;} @Override public HandlerList getHandlers(){return HANDLERS;} public static HandlerList getHandlerList(){return HANDLERS;} }
